insert into testimonials(id,data) values('t1','{"id":"t1","name":"Sofia R.","stars":5,"text":{"en":"The most meticulous manicure I''ve ever had. Crystal doesn''t rush a single cuticle — my Russian manicure still looked fresh three weeks later.","es":"La manicura más meticulosa que he tenido. Crystal no se apresura con nada — mi manicura rusa se veía fresca tres semanas después."}}'::jsonb) on conflict(id) do nothing;
insert into testimonials(id,data) values('t2','{"id":"t2","name":"Daniela M.","stars":5,"text":{"en":"I showed her a vague idea and she painted actual art on my nails. I''ve never gotten so many compliments.","es":"Le mostré una idea vaga y pintó arte de verdad en mis uñas. Nunca había recibido tantos cumplidos."}}'::jsonb) on conflict(id) do nothing;
insert into testimonials(id,data) values('t3','{"id":"t3","name":"Priya K.","stars":5,"text":{"en":"The studio feels like a private retreat. Calm, spotless, and my Gel-X set is the most natural-looking I''ve ever worn.","es":"El estudio se siente como un refugio privado. Tranquilo, impecable, y mi set Gel-X es el más natural que he usado."}}'::jsonb) on conflict(id) do nothing;
insert into testimonials(id,data) values('t4','{"id":"t4","name":"Ashley T.","stars":5,"text":{"en":"Worth every penny. Booking online took a minute and she confirmed by text right away. I''m a client for life.","es":"Vale cada centavo. Reservar en línea tomó un minuto y me confirmó por texto de inmediato. Soy clienta de por vida."}}'::jsonb) on conflict(id) do nothing;
insert into kv("key",value) values('content','{"heroKicker":{"en":"San Fernando · Luxury Nail Atelier","es":"San Fernando · Atelier de Uñas de Lujo"},"heroT1":{"en":"Nails as","es":"Uñas como"},"heroT2":{"en":"art.","es":"arte."},"heroT3":{"en":"Luxury in","es":"Lujo en"},"heroT4":{"en":"every detail.","es":"cada detalle."},"heroSub":{"en":"Crystal Maciel crafts couture manicures — from glass-perfect Russian technique to hand-painted couture art — in an intimate private studio.","es":"Crystal Maciel crea manicuras de alta costura — desde la impecable técnica rusa hasta arte pintado a mano — en un íntimo estudio privado."},"heroCta1":{"en":"Book Appointment","es":"Reservar Cita"},"heroCta2":{"en":"Explore Services","es":"Ver Servicios"},"aboutKicker":{"en":"Meet the Artist","es":"Conoce a la Artista"},"aboutT1":{"en":"Hi, I''m","es":"Hola, soy"},"aboutT2":{"en":"Crystal.","es":"Crystal."},"aboutP1":{"en":"For nearly a decade I''ve treated nails as tiny canvases — blending European precision techniques with bold, modern artistry. My private San Fernando studio is designed as a retreat: one client at a time, unhurried, and entirely about you.","es":"Durante casi una década he tratado las uñas como pequeños lienzos — combinando técnicas europeas de precisión con un arte moderno y audaz. Mi estudio privado en San Fernando está diseñado como un refugio: una clienta a la vez, sin prisa y todo sobre ti."},"aboutP2":{"en":"I specialize in Russian e-file manicures, Gel-X extensions, and hand-painted couture nail art. Every set is customized to your hands, your style, and your life.","es":"Me especializo en manicura rusa con torno, extensiones Gel-X y arte de uñas de alta costura pintado a mano. Cada set se personaliza según tus manos, tu estilo y tu vida."},"aboutRole":{"en":"Founder & Master Nail Artist","es":"Fundadora y Maestra en Uñas"},"aboutBullets":[{"en":"Russian e-file technique for glass-smooth cuticles","es":"Técnica rusa con torno para cutículas perfectas"},{"en":"Premium, hypoallergenic products only","es":"Solo productos premium e hipoalergénicos"},{"en":"Hand-painted art — no stickers, no shortcuts","es":"Arte pintado a mano — sin calcomanías ni atajos"},{"en":"Private studio — one client at a time","es":"Estudio privado — una clienta a la vez"}],"address":"811 San Fernando Rd. Ste. 201, San Fernando, CA 91340","phone":"(747) 214-1272","phoneHref":"tel:+17472141272","hours":[{"d_en":"Tuesday – Saturday","d_es":"Martes – Sábado","t":"10:00 AM – 7:00 PM"},{"d_en":"Sunday","d_es":"Domingo","t":"11:00 AM – 5:00 PM"},{"d_en":"Monday","d_es":"Lunes","t":"Closed"}],"stats":{"years":"8","sets":"12k+","rating":"5.0"},"mapUrl":"https://www.google.com/maps/search/?api=1&query=811+San+Fernando+Rd+Ste+201+San+Fernando+CA+91340","footerTag":{"en":"Couture nails, crafted one client at a time in the heart of San Fernando.","es":"Uñas de alta costura, creadas una clienta a la vez en el corazón de San Fernando."}}'::jsonb) on conflict("key") do nothing;
